import threading,time,serial
from serial.tools import list_ports
ids={'GW':'40:4C:CA:5D:0A:00','EMU':'40:4C:CA:5D:01:D8'}
ports={}
end=time.time()+10
while time.time()<end:
    ps=list(list_ports.comports())
    ok=True
    for name,sn in ids.items():
        m=[p for p in ps if p.serial_number==sn and p.vid==0x303A]
        if len(m)!=1: ok=False; break
        ports[name]=m[0].device
    if ok and ports['GW']!=ports['EMU']: break
    time.sleep(0.2)
else: raise SystemExit('failed to resolve both C6 ports after reset')
print('CAPTURE_PORTS='+repr(ports))
logs={'GW':[],'EMU':[]}
stop=time.time()+90
def reader(name):
    with serial.Serial(ports[name],115200,timeout=0.12) as s:
        while time.time()<stop:
            b=s.readline()
            if b:
                t=b.decode('utf-8','replace').rstrip('\r\n')
                logs[name].append(t); print(f'{name}: {t}',flush=True)
threads=[threading.Thread(target=reader,args=(n,),daemon=True) for n in ('GW','EMU')]
for t in threads:t.start()
for t in threads:t.join()
for name in ('GW','EMU'):
    open(f'/tmp/c6_ias_e2e_after_fix_{name.lower()}.log','w').write('\n'.join(logs[name])+'\n')
    print(f'{name}_LINES={len(logs[name])}')
g='\n'.join(logs['GW']); e='\n'.join(logs['EMU'])
print('EMU_STARTED='+str('selected Zigbee emulator profile started' in e))
print('EMU_TICK='+str('emulator tick=' in e))
print('EMU_ABORT='+str('abort() was called' in e or 'Guru Meditation' in e))
