 ('GW_CONTACT',['CONTACT_OPEN','contact_open','contact open'],g),
 ('EMU_JOIN',['joined','join','steering'],e),
 ('EMU_REPORT_OK',['report request'],e)]:
    print(label+'_HITS='+str(sum(text.lower().count(x.lower()) for x in terms)))
print('=== GW RELEVANT ===')
for line in logs['GW']:
